// ─────────────────────────────────────────────────────────────
//  FLAT MILESTONE LOOKUP  -  O(1) access by milestone id
//  Populated once at load time.  { milestoneId → { milestone, category } }
// ─────────────────────────────────────────────────────────────

var _MILESTONE_MAP = {};

(function _buildMilestoneMap() {
    LEDGER_CATEGORIES.forEach(cat => {
        cat.milestones.forEach(ms => {
            _MILESTONE_MAP[ms.id] = { milestone: ms, category: cat };
        });
    });
})();
//--- globalThis bridge (function/var): js/quests/quests-data.js ---
try { globalThis["_atlasTierCheck"] = _atlasTierCheck; } catch (e) {}
try { globalThis["_MILESTONE_MAP"] = _MILESTONE_MAP; } catch (e) {}
try { globalThis["LEDGER_CATEGORIES"] = LEDGER_CATEGORIES; } catch (e) {}
try { globalThis["LEDGER_GROUPS"] = LEDGER_GROUPS; } catch (e) {}

