try { globalThis["RARITY_COLOR_MAP"] = RARITY_COLOR_MAP; } catch (e) {}
try { globalThis["APEX_COLLECTOR_VALID_RARITIES"] = APEX_COLLECTOR_VALID_RARITIES; } catch (e) {}
try { globalThis["COMMON_REFINEMENT_UPGRADES"] = COMMON_REFINEMENT_UPGRADES; } catch (e) {}
try { globalThis["NODE_LOCKED_ITEMS"] = NODE_LOCKED_ITEMS; } catch (e) {}
