﻿// penalty.js
// Handles all penalty behaviour on a wrong cell guess:
// shield absorption, Black Swan interruption, passive skill procs,
// time deduction with modifier stacking, HUD feedback, and game-over check.

//------------------------------------------------------------------------
//-------------------CONSTANTS & STATE-------------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

var PEN_FLASH_DURATION_MS = 350;    // Duration of the red screen flash in milliseconds
var PEN_INFO_CLEAR_DELAY_MS = 3000; // How long the penalty label stays visible in the HUD


//------------------------------------------------------------------------
//-------------------SHIELD / BLACK SWAN HELPERS--------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Returns true if the current penalty multiplier signals a full shield absorption (penMult === 0).
// Shows toast and plays the shield SFX when absorbed.
function _penaltyIsShieldAbsorbed(penMult) {
    if (penMult !== 0) return false;
    showToast(t('pen_shield'));
    Audio_Manager.playSFX('shield_break');
    return true;
}

// If Black Swan (SPEEDFORCE) is currently active, end it and notify the player.
// Called before any real penalty is applied, since a mistake breaks the streak.
function _interruptBlackSwanIfActive() {
    if (!window._blackSwanActive) return;
    _endBlackSwan(false);
    showToast(t('cg_speedforce_broken'));
}


//------------------------------------------------------------------------
//-------------------PASSIVE SKILL PROC HELPERS---------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// keystone_stochastic_resonance (node 265):
// On mistake, 25% chance to reveal 1 correct cell instead of applying a penalty.
// Cannot trigger twice in a row (anti-repeat guard via window._stochasticLastFired).
// Returns true if the proc fired (caller should skip the rest of penalty logic).
function _tryProcStochasticResonance(row, col) {
    const canProc = ptHasSkill('keystone_stochastic_resonance') && !window._stochasticLastFired;
    if (canProc && Math.random() < 0.25) {
        window._stochasticLastFired = true;
        const revealed = revealTiles(1);
        if (revealed && revealed.length > 0) {
            // Pass four arguments: mistake coordinates, followed by target coordinates
            playStochasticResonanceEffect(row, col, revealed[0].row, revealed[0].col);
        }
        Audio_Manager.playSFX('stochastic_resonance');
        showToast(`〰️ ${t('cg_stoch_resonance')}`);
        return true; // penalty absorbed - no mistakeCount increment, no time loss
    }
    window._stochasticLastFired = false;
    return false;
}

// standard_deviation (nodes 255–257):
// Reveals cells after a threshold number of mistakes.
//   Node 1 only   → every 3 mistakes → reveal 1 cell
//   Nodes 1+2     → every 2 mistakes → reveal 1 cell
//   Nodes 1+2+3   → every 2 mistakes → reveal 2 cells
// Also checks for a pending Bayesian bonus reveal on top of the base reveals.
// Fires beam effects from the mistake cell to each revealed tile.
function _tryProcStandardDeviation(mistakeRow, mistakeCol) {
    if (!ptHasSkill('standard_deviation_1')) return;

    const hasNode2 = ptHasSkill('standard_deviation_2');
    const hasNode3 = ptHasSkill('standard_deviation_3');
    const threshold = hasNode2 ? 2 : 3;

    if (mistakeCount % threshold !== 0) return;

    const revealCount = hasNode3 ? 2 : 1;
    const revealedTiles = revealTiles(revealCount) || [];

    // Bayesian bonus: extra reveal based on accumulated bonus probability
    if (_getBayesianBonus() > 0 && Math.random() < _getBayesianBonus()) {
        _resetBayesianBonus();
        const extraTiles = revealTiles(1) || [];
        revealedTiles.push(...extraTiles);
    }

    // Spawn a visual beam from the mistake cell to each revealed tile
    revealedTiles.forEach(tile => {
        if (tile && tile.row !== undefined && tile.col !== undefined) {
            createBeamEffect(mistakeRow, mistakeCol, tile.row, tile.col);
        }
    });

    Audio_Manager.playSFX('standard_deviation');
    const feedbackLabel = t('cg_error_feedback');
    const revealLabel = t(revealCount > 1 ? 'cg_cells_revealed_pl' : 'cg_cells_revealed_one')
        .replace('{n}', revealCount);

    showToast(`📏 ${feedbackLabel} ${revealLabel}`);
}


//------------------------------------------------------------------------
//-------------------PENALTY CALCULATION HELPERS--------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------
// Returns the penalty (seconds) for the Nth mistake (1-based), taken from
// the difficulty config. Clamps to the last entry once past the defined
// list, and never goes below index 0 - guards against being called before
// any mistake has happened yet (e.g. the mistakes tooltip previewing the
// "next" penalty).
function _getPenaltySecondsAtCount(count) {
    const pens = DIFF_CFG[curDiff].pens;
    let idx = count - 1;
    if (_charIs('stox')) {
        idx = Math.floor(idx * 0.7);
    }
    idx = Math.max(0, idx);
    return pens[Math.min(idx, pens.length - 1)];
}

// Returns the base penalty seconds for the current (just-made) mistake.
// Called from applyPenalty() after mistakeCount has already been incremented.
function _getBasePenaltySeconds() {
    return _getPenaltySecondsAtCount(mistakeCount);
}

// keystone_asymptotic_mastery (node 266):
// Each completed line permanently reduces all future penalties by 5 seconds.
// Returns total flat reduction in seconds.
function _getAsymptoticMasteryReduction() {
    return (window._asymptoticLinesCompleted || 0) * 5;
}

// keystone_iron_doctrine (node 158):
// Each mistake costs 60 extra seconds on top of the normal penalty.
function _getIronDoctrineExtraSeconds() {
    return ptHasSkill('keystone_iron_doctrine') ? 60 : 0;
}

// Resolves the active penalty multiplier for this mistake.
// Overfitting node overrides the class multiplier when active;
// otherwise the class multiplier (penMult) is used.
function _resolveActivePenaltyMultiplier(penMult) {
    const overfitMult = _overfittingPenaltyMultiplier();
    return (overfitMult !== null) ? overfitMult : penMult;
}

// Combines base seconds, multiplier, and flat reduction into the final penalty.
// Always returns a non-negative integer.
function _calcEffectivePenalty(penMult) {
    const base = _getBasePenaltySeconds();
    const multiplier = _resolveActivePenaltyMultiplier(penMult);
    const reduction = _getAsymptoticMasteryReduction();
    return Math.max(0, Math.round(base * multiplier) - reduction + _getIronDoctrineExtraSeconds());
}


//------------------------------------------------------------------------
//-------------------TIMER & GAME-STATE HELPERS---------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Deducts the effective penalty from the timer, refreshes the HUD clock,
// and logs the mistake to the Actuary system.
// keystone_golden_clock: while the Golden Clock is active the timer can no
// longer decrease, so mistake deductions are skipped entirely.
function _applyTimeDeduction(row, col, effectivePen) {
    if (window.STOX_FLAGS.goldenClockActive) {
        updTimer();
        return;
    }
    timerSecs = Math.max(0, timerSecs - effectivePen);
    updTimer();
    if (effectivePen > 0) {
        actuaryLogMistake(row, col, effectivePen);
        _levelTimeLost += effectivePen;
    }
}

// Flags the penalty_clutch achievement condition:
// set when a penalty drops the timer from ≥60s to <60s (but not zero).
// scoring.js reads this flag on win to award the achievement.
function _checkAndFlagPenaltyClutch(timerBefore) {
    if (timerBefore >= 60 && timerSecs < 60 && timerSecs > 0) {
        window._hadPenaltyClutch = true;
    }
}

// Triggers game-over when the timer hits zero after a penalty.
function _checkTimerExpiry() {
    if (timerSecs <= 0) {
        dead = true;
        stopTimer();
        if (typeof _arcaneFreeze_clearAllFrostAndStalagmites === 'function') {
            _arcaneFreeze_clearAllFrostAndStalagmites();     
        }
        timesUp();
    }
}


//------------------------------------------------------------------------
//-------------------HUD FEEDBACK HELPERS---------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Formats a penalty duration (in seconds) as a HUD label.
// Displays as −M:SS when ≥60s, or −Ns for shorter amounts.
function _formatPenaltyLabel(effectivePen) {
    const mins = Math.floor(effectivePen / 60);
    const secs = effectivePen % 60;
    return mins > 0
        ? `−${mins}:${String(secs).padStart(2, '0')}`
        : `−${secs}s`;
}

// Updates the pen-info element with the penalty label and current mistake count,
// then auto-clears it after PEN_INFO_CLEAR_DELAY_MS.
function _updatePenaltyInfoHUD(effectivePen) {
    const pi = document.getElementById('pen-info');
    const label = _formatPenaltyLabel(effectivePen);
    pi.textContent = `${label} (#${mistakeCount})`;
    clearTimeout(pi._t);
    pi._t = setTimeout(() => pi.textContent = '', PEN_INFO_CLEAR_DELAY_MS);
}

// Updates the mistake counter element in the HUD (delegates the text format
// to _setMistakeCounterText, which appends "/ max" on endgame maps with a
// mistake limit), and keeps the endgame objectives + limit check in sync.
function _updateMistakeCounterHUD() {
    if (typeof _setMistakeCounterText === 'function') {
        _setMistakeCounterText();
    } else {
        const mc = document.getElementById('mistake-counter');
        if (mc) mc.textContent = `${t('cg_mistakes_lbl')}: ${mistakeCount}`;
    }

    if (typeof _egIsActive === 'function' && _egIsActive()) {
        if (typeof _egUpdateObjectivesHUD === 'function') _egUpdateObjectivesHUD();
        if (typeof _egCheckMistakeLimit === 'function') _egCheckMistakeLimit();
    }
}

// Triggers the brief red screen flash that gives tactile feedback on a mistake.
// Skipped entirely when the penalty-flash setting is disabled.
function _triggerPenaltyFlash() {
    if (!SETTINGS.penaltyFlash) return;
    const fl = document.getElementById('pen-flash');
    fl.classList.add('show');
    setTimeout(() => fl.classList.remove('show'), PEN_FLASH_DURATION_MS);
}


//------------------------------------------------------------------------
//-------------------APPLY PENALTY (MAIN ENTRY POINT)--------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Main penalty handler - called whenever the player selects a wrong cell.
// row / col: grid coordinates of the mistake, used for beam effects and actuary logging.
function applyPenalty(row, col) {
    // The Clock's Time Freeze: the mistake counter is frozen - wrong fills
    // still flash red and ring, but cost no mistake and no timer time until
    // the 30s window ends (or the boss is slain). See _egClockStartTimeFreeze.
    if (typeof window !== 'undefined' && window._egClockTimeFreezeActive) return;

    const penMult = getClassPenaltyMultiplier(); // 5.0 during Black Swan, 0 = shield absorbed

    // --- Shield check: if penMult is 0, the hit is fully absorbed; do nothing further ---
    if (_penaltyIsShieldAbsorbed(penMult)) return;

    // --- Break any active Black Swan streak before applying the penalty ---
    _interruptBlackSwanIfActive();

    // --- Stochastic Resonance: 25% chance to convert the mistake into a free reveal ---
    if (_tryProcStochasticResonance(row, col)) return;

    // --- Register the mistake and fire dependent systems ---
    mistakeCount++;
    _incDirect('lifetimeMistakesMade');
    _onMistakeBayesianUpdate();
    _gamblersRuinOnMistake();
    trackAchStat('mistakesMade');
    if (typeof onMistake === 'function') onMistake();

    // Mana on mistake (gear stat)
    if (typeof gainMana === 'function'
        && typeof _egComputePlayerStats === 'function'
        && playerMaxMana > 0) {
        gainMana(_egComputePlayerStats().manaOnMistake || 0);
    }

    // --- Character banter: react to this mistake (and to mistake streaks) ---
    if (typeof triggerBanter === 'function') {
        if (mistakeCount > 0 && mistakeCount % 3 === 0) {
            triggerBanter('mistake_streak');
        } else {
            triggerBanter('mistake_single');
        }
    }

    // --- Standard Deviation: threshold-based reveals triggered by mistake count ---
    _tryProcStandardDeviation(row, col);

    // --- Calculate and apply the time penalty ---
    let effectivePen = _calcEffectivePenalty(penMult);

    // Endgame ailment: wrong clicks on LAVA cells burn twice as hard -
    // count as a second mistake AND double the time loss.
    if (typeof _egIsLavaCell === 'function' && _egIsLavaCell(row, col)) {
        mistakeCount++;
        effectivePen *= 2;
        showToast('🌋 Lava! The mistake counts twice!');
    }

    const timerBefore = timerSecs;

    _applyTimeDeduction(row, col, effectivePen);
    _checkAndFlagPenaltyClutch(timerBefore);

    // --- Update HUD to reflect the new penalty and mistake count ---
    _updatePenaltyInfoHUD(effectivePen);
    _updateMistakeCounterHUD();
    _triggerPenaltyFlash();

    // --- End the game if the timer expired from this penalty ---
    _checkTimerExpiry();

    // NOTE: kept as-is from the original - see "Possible bugs spotted" below.
    _updateMistakeCounterHUD();
}
//--- globalThis bridge (function/var): js/penalty.js ---
try { globalThis["_penaltyIsShieldAbsorbed"] = _penaltyIsShieldAbsorbed; } catch (e) {}
try { globalThis["_interruptBlackSwanIfActive"] = _interruptBlackSwanIfActive; } catch (e) {}
try { globalThis["_tryProcStochasticResonance"] = _tryProcStochasticResonance; } catch (e) {}
try { globalThis["_tryProcStandardDeviation"] = _tryProcStandardDeviation; } catch (e) {}
try { globalThis["_getPenaltySecondsAtCount"] = _getPenaltySecondsAtCount; } catch (e) {}
try { globalThis["_getBasePenaltySeconds"] = _getBasePenaltySeconds; } catch (e) {}
try { globalThis["_getAsymptoticMasteryReduction"] = _getAsymptoticMasteryReduction; } catch (e) {}
try { globalThis["_getIronDoctrineExtraSeconds"] = _getIronDoctrineExtraSeconds; } catch (e) {}
try { globalThis["_resolveActivePenaltyMultiplier"] = _resolveActivePenaltyMultiplier; } catch (e) {}
try { globalThis["_calcEffectivePenalty"] = _calcEffectivePenalty; } catch (e) {}
try { globalThis["_applyTimeDeduction"] = _applyTimeDeduction; } catch (e) {}
try { globalThis["_checkAndFlagPenaltyClutch"] = _checkAndFlagPenaltyClutch; } catch (e) {}
try { globalThis["_checkTimerExpiry"] = _checkTimerExpiry; } catch (e) {}
try { globalThis["_formatPenaltyLabel"] = _formatPenaltyLabel; } catch (e) {}
try { globalThis["_updatePenaltyInfoHUD"] = _updatePenaltyInfoHUD; } catch (e) {}
try { globalThis["_updateMistakeCounterHUD"] = _updateMistakeCounterHUD; } catch (e) {}
try { globalThis["_triggerPenaltyFlash"] = _triggerPenaltyFlash; } catch (e) {}
try { globalThis["applyPenalty"] = applyPenalty; } catch (e) {}
try { globalThis["PEN_INFO_CLEAR_DELAY_MS"] = PEN_INFO_CLEAR_DELAY_MS; } catch (e) {}
try { globalThis["PEN_FLASH_DURATION_MS"] = PEN_FLASH_DURATION_MS; } catch (e) {}

//=======[ js/scoring.js?v=5 ]=======================================================
﻿// =============================================================================
// scoring.js
// Handles all end-of-level scoring logic: puzzle validation, score calculation,
// bonus evaluation, lucky drops, achievement hooks, special rewards, win overlay
// rendering, and the main checkWin() entry point.
// =============================================================================


//------------------------------------------------------------------------
//-------------------MODULE-LEVEL STATE-----------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Tracks points earned during the current active run.
// Set inside calculateScore() when a level is completed and referenced by
// the win overlay to show how many points were awarded vs. the previous best.
var currentRunScore = 0;


//------------------------------------------------------------------------
//-------------------PUZZLE VALIDATION------------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Returns true if every cell in the player's grid matches the solution.
// A cell counts as "filled" if the player marked it (userGrid === 1)
// or if it was revealed by a helper item (revealedGrid === true).
function isPuzzleSolved() {
    const sol = cur.grid;
    const rows = sol.length;
    const cols = sol[0].length;

    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            const playerFilled = userGrid[r][c] === 1 || revealedGrid[r][c];
            const solutionFilled = sol[r][c] === 1;
            if (playerFilled !== solutionFilled) return false;
        }
    }
    return true;
}


//------------------------------------------------------------------------
//-------------------SCORE CALCULATION------------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Returns the raw score before the multiplier is applied.
// Base score grows with grid size; remaining time adds a bonus;
// each mistake deducts points. Score is floored at 10.
function computeRawScore(rows, cols) {
    const safeRows = Number.isFinite(Number(rows)) ? Number(rows) : 0;
    const safeCols = Number.isFinite(Number(cols)) ? Number(cols) : 0;
    const baseScore = 100 + (safeRows + safeCols) * 2;

    // Time Trial halves the starting clock, which would otherwise also halve
    // the time bonus. Add back exactly what was cut so the bonus reflects
    // the same effective time budget as normal mode.
    const normalizedSecs = timerSecs + (curMods.timetrial ? (window._timetrialTimeCut || 0) : 0);

    const safeTimerSecs = Number.isFinite(Number(timerSecs)) ? Number(timerSecs) : 0;
    const safeNormalizedSecs = Number.isFinite(Number(normalizedSecs)) ? Number(normalizedSecs) : safeTimerSecs;
    const cappedTime = Math.min(Math.max(0, safeNormalizedSecs), 3600);   // cap at 1 hour to prevent abuse
    const timeBonus = Math.floor(cappedTime / 10);
    const safeMistakes = Number.isFinite(Number(mistakeCount)) ? Number(mistakeCount) : 0;
    const mistakePenalty = safeMistakes * 20;
    return Math.max(10, baseScore + timeBonus - mistakePenalty);
}

// Determines how many net-new points are awarded to the player.
// If the current run score beats the level high score, the difference is awarded.
// Otherwise nothing is awarded (the player already has a better record).
function computePointsAwarded(pts, gi) {
    const hs = STATE.levelHS[gi];
    const prevBest = hs ? hs.score : 0;
    return { ptsAwarded: Math.max(0, pts - prevBest), prevBest };
}

// Saves a new high-score entry for this level if the current run beats the record.
function maybeUpdateHighScore(gi, pts) {
    const hs = STATE.levelHS[gi];
    if (!hs || pts > hs.score) {
        STATE.levelHS[gi] = {
            score: pts,
            diff: curDiff,
            time: timerSecs,
            mods: { ...curMods },
        };
    }
}

// Master score calculation function.
// Computes the final score, awards net-new points to the player's total,
// updates the level high score if beaten, and returns all relevant values
// for display and quest-stat tracking.
function calculateScore(rows, cols) {
    const gi = cur.gIdx;
    const rawScore = computeRawScore(rows, cols);
    const calculatedMult = scoreMultiplier();
    const mult = Number.isFinite(Number(calculatedMult)) ? Number(calculatedMult) : 1;
    const calculatedPts = Math.round(rawScore * mult);
    const pts = Number.isFinite(calculatedPts) ? Math.max(0, calculatedPts) : 0;

    const { ptsAwarded, prevBest } = computePointsAwarded(pts, gi);

    const currentTotal = Number.isFinite(Number(STATE.totalScore)) ? Number(STATE.totalScore) : 0;
    STATE.totalScore = currentTotal + ptsAwarded;
    maybeUpdateHighScore(gi, pts);

    return { pts, ptsAwarded, prevBest, mult };
}


//------------------------------------------------------------------------
//-------------------BONUS OBJECTIVE EVALUATION---------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Returns true if the current level's bonus condition has been satisfied.
// Each bonusType has its own pass/fail rule; unknown types default to false.
function evaluateBonusObjective(elapsed) {
    const bt = cur.bonusType || 'nomiss';
    const bp = cur.bonusParam !== undefined ? cur.bonusParam : 0;

    switch (bt) {
        case 'fast': return elapsed <= bp;
        case 'nomiss': return mistakeCount === 0;
        case 'lowmiss': return mistakeCount <= bp;
        case 'noitem': return itemsUsedThisLevel === 0;
        case 'quiz': return true;   // quiz bonus is evaluated separately via showQuiz()
        case 'combo': return elapsed <= bp && mistakeCount === 0;
        case 'noitem_nomiss': return itemsUsedThisLevel === 0 && mistakeCount === 0;
        case 'noitem_fast': return itemsUsedThisLevel === 0 && elapsed <= bp;
        default: return false;
    }
}


//------------------------------------------------------------------------
//-------------------ACHIEVEMENT HOOKS------------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Counts how many solution cells are filled (value === 1) in the grid.
function countFilledCells(sol, rows, cols) {
    let count = 0;
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            if (sol[r][c] === 1) count++;
    return count;
}

// Counts how many cells the player has cross-marked (userGrid value === 2).
function countMarkedCells(rows, cols) {
    if (!userGrid) return 0;
    let count = 0;
    for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
            if (userGrid[r][c] === 2) count++;
    return count;
}

// Fires the achievement system's level-complete hook with all relevant stats,
// then clears the per-run window flags used by penalty-clutch and bounceback logic.
function fireAchievements({ gi, rows, cols, elapsed, pts, ptsAwarded, prevBest, mult, isFirstClear }) {
    const sol = cur.grid;
    const totalCells = rows * cols;
    const cellsFilled = countFilledCells(sol, rows, cols);
    const tilesMarked = countMarkedCells(rows, cols);

    onLevelCompleteAch({
        mistakes: mistakeCount,
        itemsUsed: itemsUsedThisLevel,
        diff: curDiff,
        mods: curMods,
        playerClass: STATE.playerClass || null,
        playerAscendency: STATE.playerAscendency || null,
        absorbedMistakes: absorbedMistakes,
        absorbedThisLevel: absorbedMistakes,
        cellsFilled,
        tilesMarked,
        totalCells,
        rows,
        cols,
        scoreEarned: pts,
        world: cur.world,
        gi,
        elapsed,
        timerSecs,
        pts,
        prevBest,
        mult,
        isFirstClear,
        hadPenaltyClutch: !!window._hadPenaltyClutch,
        isBouncebackWin: window._lastFailedGi === gi,
    });

    // Reset transient run flags consumed by the achievement system
    window._hadPenaltyClutch = false;
    window._lastFailedGi = null;

    checkWorldCompleteAch();
}


//------------------------------------------------------------------------
//-------------------ITEM REWARD HELPERS-----------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Wraps reward content in the standard item-reward card markup shared by
// bonus rewards, lucky drops, and the ascension codex reward.
function _buildItemRewardCard(defId, def, labelHtml) {
    const rc = rarityColors(def.rarity);
    return `
        <div class="item-reward" data-reward-defid="${defId}"
             style="border-color:${rc.border};color:${rc.color};cursor:default;">
            ${labelHtml}
        </div>`;
}


//------------------------------------------------------------------------
//-------------------CONVERGENCE REWARD-----------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Convergence milestones no longer live on campaign puzzle levels (Leveling
// Rework): every former convergence level is a REGULAR puzzle level now.
// Passive points for milestones come from Convergence Trials instead (see
// js/campaign-trials.js). Kept as a function because quest stats, the world
// screens and old saves still call it; it always reports "not convergence".
function isConvergenceLevel(worldData, isAscensionLevel) {
    return false;
}

// Grants one passive tree point on the first clear of a convergence level
// and queues the convergence modal for display after the win overlay closes.

function applyConvergenceReward(gi) {
    if (!STATE.convergenceDone) STATE.convergenceDone = [];
    const isFirstEver = STATE.convergenceDone.length === 0;
    STATE.convergenceDone.push(gi);
    STATE.passiveTreePoints = (STATE.passiveTreePoints || 0) + 1;
    _incDirect('lifetimePassivePointsObtained', 1);
    save();
    window._pendingConvergenceModal = true;

    if (isFirstEver) {
        //showBeat('first_convergence');
    }
}


//------------------------------------------------------------------------
//-------------------ASCENSION REWARD-------------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Grants the Codex of Completion artifact on the first clear of the final
// level in a world (the ascension level), and writes its reward HTML into irz.
// Does nothing in ironman mode - that mode disables item rewards.
function applyAscensionReward(irz) {
    const defId = 'artifactComplete';
    const codexDef = ITEM_DEFS[defId];

    STATE.inventory.push({
        defId,
        uid: `item_${Date.now()}_${Math.random().toString(36).slice(2)}`,
    });
    save();

    buildInventoryPanel();
    showItemGainPopup(defId);

    const label = `🌟 ${t('cg_ascension_reward')}:
            ${codexDef.icon} <strong>${itemName(codexDef)}</strong>`;
    irz.innerHTML = _buildItemRewardCard(defId, codexDef, label);
}

// Builds the Nexus Point unlock card shown in the win overlay's reward zone.
function applyNexusPointReward(irz) {
    if (typeof setNexusUnlocked === 'function') setNexusUnlocked();
    else if (typeof STATE !== 'undefined' && STATE) {
        STATE.nexusUnlocked = true;
        if (typeof save === 'function') save();
    }
    if (!irz) return;
    const label = `🌌 ${t('scr_nexus_unlocked_title')}: ${t('scr_enter_nexus_short')}`;
    irz.innerHTML += `<div class="item-reward" style="border-color:#7fd4ff;color:#bfe9ff;cursor:default;">${label}<br><span style="opacity:0.8;font-size:0.9em">${t('scr_nexus_unlocked_desc')}</span></div>`;
    if (typeof showToast === 'function') showToast(`🌌 ${t('scr_nexus_unlocked_title')}`);
}

// Dispatcher for convergence, ascension and Nexus Point one-time rewards.
// Called during win-overlay rendering; writes into the item-reward zone (irz)
// when a special reward applies. The Nexus Point never grants the ascension
// codex - it unlocks the Nexus instead.
function handleSpecialRewards({ gi, isFirstClear, isAscensionLevel, irz, isNexusPoint }) {
    const worldData = WORLDS[cur.world - 1];

    if (isConvergenceLevel(worldData, isAscensionLevel) && isFirstClear) {
        applyConvergenceReward(gi);
    }

    if (isNexusPoint) {
        if (isFirstClear) applyNexusPointReward(irz);
        return;
    }

    if (isAscensionLevel && isFirstClear && !curMods.ironman) {
        applyAscensionReward(irz);
    }
}


//------------------------------------------------------------------------
//-------------------LUCKY DROPS------------------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Returns the total drop chance for lucky drops based on allocated passive nodes.
// Base chance is 25%; each bonus_replay node adds an additional percentage.
function getLuckyDropChance() {
    let chance = 0.25;
    if (ptHasSkill('bonus_replay_1')) chance += 0.10;
    if (ptHasSkill('bonus_replay_2')) chance += 0.15;
    if (ptHasSkill('bonus_replay_3')) chance += 0.20;
    if (_charIs('trix')) chance += 0.15;
    return chance;
}

// Returns the chance of receiving a second lucky drop item.
// Each lucky_replay node contributes an additive percentage.
function getExtraItemChance() {
    return (ptHasSkill('lucky_replay_1') ? 0.10 : 0)
        + (ptHasSkill('lucky_replay_2') ? 0.15 : 0)
        + (ptHasSkill('lucky_replay_3') ? 0.20 : 0);
}

// Decides how many lucky drop items to grant this trigger (1 or 2).
function rollLuckyDropCount() {
    return Math.random() < getExtraItemChance() ? 2 : 1;
}

// Builds the HTML for a single lucky-drop item reward and adds it to the inventory.
function grantLuckyDropItem() {
    const defId = pickRandomItem();
    if (!defId) return '';

    const def = ITEM_DEFS[defId];
    if (!def) return '';

    STATE.inventory.push({ defId, uid: Date.now() + Math.random().toString(36).slice(2) });

    buildInventoryPanel();
    showItemGainPopup(defId);

    const label = `${t('ov_lucky_drop')} ${def.icon} <strong>${itemName(def)}</strong>`;
    return _buildItemRewardCard(defId, def, label);
}

// Attempts to trigger lucky drops for this level completion.
// Requires the lucky_drops passive node to be allocated.
// Returns an HTML string of all item-reward divs granted, or '' if none triggered.
function rollLuckyDrops() {
    if (!ptHasSkill('lucky_drops') && !_charIs('trix')) return '';
    if (Math.random() >= getLuckyDropChance()) return '';

    questStat_luckyDropClaimed();

    const count = rollLuckyDropCount();
    let html = '';
    for (let i = 0; i < count; i++) {
        html += grantLuckyDropItem();
    }

    if (html) save();
    return html;
}


//------------------------------------------------------------------------
//-------------------WIN OVERLAY HELPERS----------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Formats a time in seconds as "M:SS".
function formatTime(totalSeconds) {
    const mins = Math.floor(totalSeconds / 60);
    const secs = totalSeconds % 60;
    return `${mins}:${String(secs).padStart(2, '0')}`;
}

// Builds the gain-note string shown next to the score.
// If a new record was set, shows the net-new points and the previous best.
// Otherwise shows just the total points awarded.
function buildGainNote(pts, ptsAwarded, prevBest) {
    if (ptsAwarded < pts) {
        return ` (+${ptsAwarded} ${t('ov_win_new')} - ${t('ov_win_best_was')} ${prevBest})`;
    }
    return ` (+${ptsAwarded})`;
}

// Returns the appropriate HTML line for the mistake count.
// Handles the three distinct display states: no mistakes, all absorbed, partial absorbed.
function buildMistakeLine() {
    const totalWrongClicks = mistakeCount + absorbedMistakes;

    if (totalWrongClicks === 0) {
        return `<div class="ov-sub-line ov-sub-miss-ok">✗ 0 ${t('ov_win_mistakes')}</div>`;
    }

    const absorbedNote = `<span style="opacity:0.55;font-size:0.85em">(${absorbedMistakes} ${t('ov_win_absorbed')})</span>`;

    if (absorbedMistakes > 0 && mistakeCount === 0) {
        // All wrong clicks were absorbed - still shows as a clean run
        return `<div class="ov-sub-line ov-sub-miss-ok">✗ 0 ${t('ov_win_mistakes')} ${absorbedNote}</div>`;
    }

    const mistakeWord = mistakeCount !== 1 ? t('ov_win_mistakes') : t('ov_win_mistake');
    const cssClass = mistakeCount === 0 ? 'ov-sub-miss-ok' : 'ov-sub-miss';

    if (absorbedMistakes > 0) {
        return `<div class="ov-sub-line ${cssClass}">✗ ${mistakeCount} ${mistakeWord} ${absorbedNote}</div>`;
    }

    return `<div class="ov-sub-line ${cssClass}">✗ ${mistakeCount} ${mistakeWord}</div>`;
}

function buildScoreColumn(pts, ptsAwarded, prevBest, mult) {
    const safeMult = Number.isFinite(Number(mult)) ? Number(mult) : 1;
    const gainNote = buildGainNote(pts, ptsAwarded, prevBest);
    document.getElementById('ov-col-score').innerHTML = `
        <div class="ov-sub-line ov-sub-pts">${pts} ${t('ov_win_pts')}</div>
        <div class="ov-sub-line ov-sub-pts">${t('ov_win_multiplier')} ×${safeMult.toFixed(2)}</div>
        <div class="ov-sub-line ov-sub-pts">${gainNote}</div>`;
}

function buildTimeColumn(elapsed) {
    document.getElementById('ov-col-time').innerHTML = `
        <div class="ov-sub-line ov-sub-time">
            ⏱ ${formatTime(timerSecs)} ${t('ov_win_left')} · ${t('ov_win_solved_in')} ${formatTime(elapsed)}
        </div>
        ${buildMistakeLine()}`;
}

// Writes the bonus badge into #bonus-list.
// Shows a success badge if the bonus was met, or the bonus hint if it was missed.
function renderBonusBadge(bonusMet) {
    document.getElementById('bonus-list').innerHTML = `
        <span class="bonus-badge ${bonusMet ? 'earned' : 'missed'}">
            ${bonusMet ? t('ov_bonus_met') : '🎯 ' + lvText(cur, 'bonusHint')}
        </span>`;
}

// Builds the HTML for a guaranteed first-time bonus item reward,
// adds it to the inventory, and saves.
function grantBonusItem() {
    const defId = pickRandomItem();
    if (!defId) return '';

    const def = ITEM_DEFS[defId];
    if (!def) return '';

    STATE.inventory.push({ defId, uid: Date.now() + Math.random().toString(36).slice(2) });
    save();

    buildInventoryPanel();
    showItemGainPopup(defId);

    const label = `${t('ov_item_earned')}: ${def.icon} <strong>${itemName(def)}</strong>`;
    return _buildItemRewardCard(defId, def, label);
}

// Returns the HTML for the "bonus already claimed" notice shown on repeat clears.
function buildBonusClaimedNote() {
    return `<div class="item-reward" style="border-color:var(--border2);color:#666;">
        ${t('ov_bonus_claimed_note')}
    </div>`;
}

// Writes item rewards into the item-reward zone (irz) based on bonus state.
// Priority order:
//   1. First-time bonus clear → guaranteed item
//   2. Repeat bonus clear     → "already claimed" note + lucky drop chance
//   3. Bonus missed           → lucky drop chance only
// Ironman mode and quiz bonuses suppress all item rewards.
function renderItemRewardZone(gi, bonusMet, isFirstClear, isAscensionLevel, isNexusPoint) {
    const irz = document.getElementById('item-reward-zone');
    irz.innerHTML = '';
    const bonusAlreadyDone = STATE.bonusDone.includes(gi);
    const isQuizBonus = cur.bonusType === 'quiz';

    // Special one-time rewards (convergence points, ascension codex, Nexus unlock) go first
    handleSpecialRewards({ gi, isFirstClear, isAscensionLevel, irz, isNexusPoint });

    // Mark the bonus as done on first clear (before item logic so save() is called once)
    if (bonusMet && !bonusAlreadyDone && !isQuizBonus) {
        STATE.bonusDone.push(gi);
        save();
        // Re-check world aggregates - claiming this bonus may have completed
        // the "all bonuses in a world" achievement set.
        if (typeof checkWorldCompleteAch === 'function') checkWorldCompleteAch();
    }

    // Item drops are suppressed in ironman mode and for quiz bonus levels
    if (curMods.ironman || isQuizBonus) return;

    if (bonusMet && !bonusAlreadyDone) {
        irz.innerHTML += grantBonusItem();
    } else if (bonusMet && bonusAlreadyDone) {
        irz.innerHTML += buildBonusClaimedNote();
        irz.innerHTML += rollLuckyDrops();
    } else {
        irz.innerHTML += rollLuckyDrops();
    }

    // Attach hover tooltips to every item-reward card
    setTimeout(() => {
        irz.querySelectorAll('[data-reward-defid]').forEach(el => {
            attachItemTooltip(el, el.dataset.rewardDefid);
        });
    }, 0);
}

// Orchestrates the full win overlay render: stats, bonus badge, and item rewards.
function renderWinOverlay({ gi, pts, ptsAwarded, prevBest, mult, elapsed, bonusMet, isAscensionLevel, isFirstClear, isNexusPoint }) {
    document.getElementById('ov-reveal-quote').innerHTML = `"${lvText(cur, 'reveal')}"`;
    buildScoreColumn(pts, ptsAwarded, prevBest, mult);
    buildTimeColumn(elapsed);
    renderBonusBadge(bonusMet);
    renderItemRewardZone(gi, bonusMet, isFirstClear, isAscensionLevel, isNexusPoint);

    // Ascension levels always route back to the overworld: hide Next/Retry
    // and promote the Levels button to the primary action.
    // The Nexus Point behaves the same, but gains a dedicated gateway
    // button into the Nexus screen (separate element, so the static
    // Next/Levels handlers wired in ui-events.js keep working untouched).
    const nextBtn = document.getElementById('btn-next-lvl');
    const retryBtn = document.getElementById('btn-win-retry');
    const levelsBtn = document.getElementById('btn-win-levels');
    const endOfLine = isAscensionLevel || isNexusPoint;
    if (nextBtn) nextBtn.style.display = endOfLine ? 'none' : '';
    if (retryBtn) retryBtn.style.display = endOfLine ? 'none' : '';
    if (levelsBtn) levelsBtn.className = endOfLine ? 'ob p' : 'ob s';
    // The buttons live in per-column wrappers (LEVELS | REPLAY pair | NEXT);
    // a fully hidden column must collapse so the row re-centres instead of
    // leaving an empty gap (ascension / Nexus Point wins hide Next+Replay).
    const nextCol = nextBtn ? nextBtn.closest('.ov-btns-col') : null;
    if (nextCol) nextCol.style.display = endOfLine ? 'none' : '';
    _updateNexusWinButton(isNexusPoint);
    _updateConvergenceTrialWinButton(gi);
}

// Ensures the win overlay has a dedicated "Enter Convergence Trial" button.
// Shown after clearing one of the world's two convergence milestone levels
// (33% / 66% rule) when that completion unlocked (or re-unlocked) the world's
// trial. Mirrors the Nexus win button pattern: own id, static Next/Levels
// handlers untouched.
function _updateConvergenceTrialWinButton(gi) {
    const container = document.querySelector('#ov-win .ov-btns');
    if (!container) return;
    const nextBtn = document.getElementById('btn-next-lvl');
    const target = (nextBtn && nextBtn.closest('.ov-btns-col')) || container;

    // Show condition: this win IS a trigger level AND the trial is now
    // unlocked AND not already completed. Everything else hides it.
    let show = false;
    let wi = null;
    try {
        wi = cur.world - 1;
        const level = ALL[gi];
        const triggers = (typeof _egTrialTriggerLevels === 'function') ? _egTrialTriggerLevels(wi) : null;
        const isTrigger = !!(level && triggers && triggers.includes(level.li - 1));
        show = isTrigger
            && typeof _egIsTrialUnlocked === 'function' && _egIsTrialUnlocked(wi)
            && typeof _egIsTrialDone === 'function' && !_egIsTrialDone(wi);
    } catch (e) { show = false; }

    let btn = document.getElementById('btn-enter-trial-win');
    if (!btn) {
        btn = document.createElement('button');
        btn.id = 'btn-enter-trial-win';
        btn.className = 'ob y';
        btn.addEventListener('click', () => {
            hideResultOverlays();
            if (typeof _egLaunchCampaignTrial === 'function') _egLaunchCampaignTrial(wi);
            else goToLevelSelect();
        });
        target.appendChild(btn);
    }
    const label = (typeof t === 'function') ? t('btn_enter_trial_win') : null;
    btn.textContent = (label && label !== 'btn_enter_trial_win') ? label : '🌿 ENTER CONVERGENCE TRIAL';
    btn.style.display = show ? '' : 'none';
    if (show && target.classList && target.classList.contains('ov-btns-col')) {
        target.style.display = '';
    }
}

// Ensures the win overlay has a dedicated "Enter the Nexus" button.
// Created once, then shown only after the Nexus Point. Uses its own id so
// it never collides with the static Next/Levels handlers.
function _updateNexusWinButton(show) {
    const container = document.querySelector('#ov-win .ov-btns');
    if (!container) return;
    // Prefer the NEXT column wrapper (the Nexus button occupies Next's slot
    // on Nexus Point wins, where Next itself is hidden); fall back to the
    // bare container for any markup without column wrappers.
    const nextBtn = document.getElementById('btn-next-lvl');
    const target = (nextBtn && nextBtn.closest('.ov-btns-col')) || container;
    let btn = document.getElementById('btn-enter-nexus-win');
    if (!btn) {
        btn = document.createElement('button');
        btn.id = 'btn-enter-nexus-win';
        btn.className = 'ob p';
        btn.addEventListener('click', () => {
            hideResultOverlays();
            if (typeof showEndgameNexus === 'function') showEndgameNexus();
            else goToLevelSelect();
        });
        target.appendChild(btn);
    } else if (btn.parentElement !== target) {
        target.appendChild(btn);
    }
    btn.textContent = t('scr_enter_nexus_short');
    btn.style.display = show ? '' : 'none';
    // On Nexus wins the Next column was hidden a moment earlier (endOfLine);
    // re-show the wrapper so the Nexus button is actually rendered.
    if (show && target.classList && target.classList.contains('ov-btns-col')) {
        target.style.display = '';
    }
}


//------------------------------------------------------------------------
//-------------------QUEST STAT HELPERS-----------------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Returns true if the current level sits at a convergence milestone
// (33% or 66% through the world) and has not been flagged as an ascension level.
// Used for quest stat tracking inside checkWin().
function checkIsConvergenceLevel(worldData, isAscensionLevel) {
    return isConvergenceLevel(worldData, isAscensionLevel);
}

// Returns true if this level completion is the one that finishes the entire world
// for the first time, and the world hasn't already been counted in quest stats.
// Prevents replays and already-counted worlds from triggering duplicate stat updates.
function checkWorldJustCompleted(worldData, isFirstClear) {
    if (!isFirstClear) return false;

    const wi = cur.world - 1;
    const start = WORLD_START_GI[wi];
    const allDone = worldData.data.every((_, li) => STATE.done.includes(start + li));
    if (!allDone) return false;

    STATE.questStats = STATE.questStats || {};
    const counted = STATE.questStats._worldsCountedList || [];
    return !counted.includes(wi);
}

// Returns true if this is a "large" level (200+ cells) and the player
// has the adjacency_matrix passive skill allocated.
function checkIsLargeAdjMatrix() {
    const rows = cur.grid.length;
    const cols = cur.grid[0].length;
    return (rows * cols >= 200) && ptHasSkill('adjacency_matrix');
}





function _getLevelSpecialStatus(level) {
    const worldData = WORLDS[level.world - 1];
    // Tutorial-quest levels live outside the WORLDS array (world 15) - they
    // are never ascension/convergence/nexus levels.
    if (!worldData) return { isAscension: false, isConvergence: false, isNexusPoint: false };
    const wi = level.world - 1;
    const li = level.li - 1;
    const isNexusPoint = typeof isNexusPointLevel === 'function'
        ? isNexusPointLevel(wi, li)
        : (wi === 13 && li === worldData.data.length - 1);
    const isAscension = !isNexusPoint && level.li === worldData.data.length;
    const isConvergence = isConvergenceLevel(worldData, isAscension);
    return { isAscension, isConvergence, isNexusPoint };
}






//------------------------------------------------------------------------
//-------------------CHECK WIN (MAIN ENTRY POINT)-------------------------
//------------------------------------------------------------------------
//------------------------------------------------------------------------

// Called after every valid cell change to check whether the puzzle is complete.
// If solved, halts the game, calculates the final score, fires all end-of-level
// hooks (achievements, rewards, quest stats), and shows the win overlay.

function checkWin() {
    if (!isPuzzleSolved()) return;

    // Monster levels hand off to the encounter chain instead of the normal
    // win flow. Campaign levels also run monsters (cur.campaignMonsters) but
    // must still complete as normal puzzle levels, so they are excluded.
    if (typeof _egIsActive === 'function' && _egIsActive()
        && !(cur && cur.campaignMonsters)) {
        if (typeof _egOnPuzzleComplete === 'function') {
            dead = true;
            stopTimer();
            _egOnPuzzleComplete();
            return;           // skip all normal scoring / overlay logic
        }
    }

    // Map-device run: puzzle solved by start-of-level passives BEFORE the
    // encounter flag has flipped (initial puzzle only). The normal
    // win/scoring path must NOT run - the puzzle belongs to the encounter
    // chain (question modal → countdown → next puzzle). Suppress the normal
    // overlay here; _doStartLevel() will hand off to _egOnPuzzleComplete
    // immediately after it starts the encounter.
    if (window._egIsMapDeviceRun && cur && cur.isMonsterLevel
        && typeof _egOnPuzzleComplete === 'function'
        && typeof _egIsActive === 'function' && !_egIsActive()) {
        return;
    }


    // Stop any active visual effects and freeze the game state
    if (typeof window.clearActiveRandomWalkers === "function") window.clearActiveRandomWalkers();
    if (typeof resetRecursionistState === "function") resetRecursionistState(); // removes the DoF zombie + Residual skeletons
    dead = true;
    stopTimer();

    if (typeof _arcaneFreeze_clearAllFrostAndStalagmites === 'function') {
        _arcaneFreeze_clearAllFrostAndStalagmites();     
    }

    // Gather level context
    const sol = cur.grid;
    const rows = sol.length;
    const cols = sol[0].length;
    const gi = cur.gIdx;
    const worldData = WORLDS[cur.world - 1];
    if (!worldData) return;   // tutorial-quest levels bypass the normal win flow
    const _special = _getLevelSpecialStatus(cur);
    const isAscensionLevel = _special.isAscension;
    const isNexusPoint = !!_special.isNexusPoint;
    const isFirstClear = !STATE.done.includes(gi);

    if (isFirstClear) STATE.done.push(gi);

    // Campaign XP: a first clear grants the full amount, a replay a fraction
    // of it (see _egGrantCampaignLevelXP / EG_LEVELING_CONFIG). Endgame map
    // runs return above via _egOnPuzzleComplete and never reach this path.
    if (typeof _egGrantCampaignLevelXP === 'function') {
        try { _egGrantCampaignLevelXP(gi, isFirstClear); } catch (e) {}
    }
    // Region entry beat - fires on first clear of that world's designated trigger level
    /*
    if (isFirstClear && cur.li === (REGION_BEAT_TRIGGER_LEVEL[cur.world] || 1)) {
        showBeat('region_' + cur.world);
    }
    */

    _wdSyncSpriteToLevel(gi);    // move sprite to the just completed level

    // Track per-level mistake record for the "flawless world" achievement.
    // Always keep the best (lowest) mistake count across replays.
    if (!STATE.levelMistakes) STATE.levelMistakes = {};
    const prevMistakeRecord = STATE.levelMistakes[gi];
    if (prevMistakeRecord === undefined || mistakeCount < prevMistakeRecord) {
        STATE.levelMistakes[gi] = mistakeCount;
    }

    const elapsed = Math.round((Date.now() - levelStartTime) / 1000);

    // Score
    const { pts, ptsAwarded, prevBest, mult } = calculateScore(rows, cols);
    save();
    document.getElementById('sc-disp').textContent = STATE.totalScore;

    // Achievements
    fireAchievements({ gi, rows, cols, elapsed, pts, ptsAwarded, prevBest, mult, isFirstClear });

    // Passive tree node rewards (gear_of_the_statistician & improved_gear)
    _ptApplyLevelCompleteRewards();

    // Bonus objective
    const bonusMet = evaluateBonusObjective(elapsed);

    if (typeof triggerBanter === 'function') triggerBanter('win');

// Render the win overlay content (buildReveal() is deferred until
    // #ov-win is actually visible - see the two branches below, and
    // finishQuiz()/skipQuiz() in quiz.js for the quiz-bonus path)
    renderWinOverlay({ gi, pts, ptsAwarded, prevBest, mult, elapsed, bonusMet, isAscensionLevel, isFirstClear, isNexusPoint });

    // World completion hooks - persist code unlocks immediately so they're
    // not lost if the player closes the game before the delayed modal shows.
    checkWorldCodesSync();
    checkWorldCompletion();

    // Show the win overlay (or quiz flow if the bonus type is 'quiz')
    if (bonusMet && cur.bonusType === 'quiz') {
        // ov-win itself isn't shown yet here - showQuiz() opens the separate
        // quiz-overlay first. buildReveal() runs later, in finishQuiz()/skipQuiz()
        // in quiz.js, right when ov-win actually becomes visible.
        setTimeout(() => showQuiz(cur.world), 1500);
    } else {
        setTimeout(() => {
            document.getElementById('ov-win').classList.add('show');
            requestAnimationFrame(() => buildReveal());
        }, 1000);
    }

    // Codes popup delayed so it feels distinct from the win overlay
    setTimeout(() => checkWorldCodes(), 2000);

    Audio_Manager.playSFX('win');

    // Quest stats update
    updateQuestStats('levelComplete', {
        gi,
        world: cur.world,
        diff: curDiff,
        mods: { ...curMods },
        mistakeCount,
        itemsUsed: itemsUsedThisLevel,
        playerClass: STATE.playerClass,
        elapsed,
        bonusMet,
        isConvergence: checkIsConvergenceLevel(worldData, isAscensionLevel) && isFirstClear,
        worldJustCompleted: checkWorldJustCompleted(worldData, isFirstClear),
        worldIndex: cur.world - 1,
        luckyDropTriggered: false,
        timerSecsAtWin: timerSecs,
        isLargeAdjMatrix: checkIsLargeAdjMatrix(),
    });

    if (typeof _endBlackSwan === "function") _endBlackSwan(false);
}
