try { globalThis["_cursedDownsideDuration"] = _cursedDownsideDuration; } catch (e) {}
try { globalThis["_cursedDownsideCount"] = _cursedDownsideCount; } catch (e) {}
try { globalThis["_blackoutWardBlocks"] = _blackoutWardBlocks; } catch (e) {}
try { globalThis["_removalWardBlocks"] = _removalWardBlocks; } catch (e) {}
try { globalThis["_applyBlackoutDownside"] = _applyBlackoutDownside; } catch (e) {}
try { globalThis["_applyRowErasureDownside"] = _applyRowErasureDownside; } catch (e) {}
try { globalThis["_applyColErasureDownside"] = _applyColErasureDownside; } catch (e) {}
try { globalThis["_resolveCursedBlackoutDownside"] = _resolveCursedBlackoutDownside; } catch (e) {}
try { globalThis["_resolveCursedRowErasureDownside"] = _resolveCursedRowErasureDownside; } catch (e) {}
