try { globalThis["_egVisTouch"] = _egVisTouch; } catch (e) {}
try { globalThis["_egVisPC"] = _egVisPC; } catch (e) {}
try { globalThis["_egVisHeal"] = _egVisHeal; } catch (e) {}
try { globalThis["_egMechVisWalls"] = _egMechVisWalls; } catch (e) {}
try { globalThis["_egMechVisBench"] = _egMechVisBench; } catch (e) {}
try { globalThis["_egMechVisQuench"] = _egMechVisQuench; } catch (e) {}
try { globalThis["_egVisFinalActive"] = _egVisFinalActive; } catch (e) {}
try { globalThis["_egVisOnPhaseEnter"] = _egVisOnPhaseEnter; } catch (e) {}
try { globalThis["_egVisEnsureFinalWatcher"] = _egVisEnsureFinalWatcher; } catch (e) {}
try { globalThis["_egVisAfter"] = _egVisAfter; } catch (e) {}
try { globalThis["_egVisFinalStart"] = _egVisFinalStart; } catch (e) {}
try { globalThis["_egVisFinalEnd"] = _egVisFinalEnd; } catch (e) {}
try { globalThis["_egVisTeardown"] = _egVisTeardown; } catch (e) {}
