                f.spiral -= dtS * 1000;
                f.ang += 3.2 * dtS;
                f.rad += 90 * dtS;
                f.x = sn.x + Math.cos(f.ang) * f.rad;
                f.y = sn.y + Math.sin(f.ang) * f.rad;
