                ring.style.left = (cn.cx - cn.r0) + 'px';
                ring.style.top = (cn.cy - cn.r0) + 'px';
                cn.rings.push({ r: cn.r0, t: 0, spawnedAt: cn.t, el: ring, hitDone: false });
                cn.spawned++;
