                // Release: the arrow arcs in from the OPPOSITE top corner so
                // the concave curve crosses the screen readably.
                m.launched = true;
                m.arrow = _egNkEl(run, 'div', 'eg-marks-arrow');
                m.sx = (m.x < window.innerWidth / 2) ? window.innerWidth + 50 : -50;
