// ── Thwomp tuning ───────────────────────────────────────────────────────
// The hovering block
var EG_THW_R = 62;                          // half-size of the block (visual + hit)
var EG_THW_HOVER_SPEED = [0, 26, 34, 44];   // px/s drift while hovering
var EG_THW_STOMP_INTERVAL_MS = [0, 8200, 6400, 4800]; // quake stomp cadence
var EG_THW_STOMP_WARN_MS = 1000;            // dust-ring telegraph
var EG_THW_STOMP_CRASH_MS = 320;            // the drop itself
var EG_THW_STOMP_R = 120;                   // impact circle radius
var EG_THW_STOMP_DMG = [0, 0.14, 0.16, 0.19]; // %maxHP per quake stomp
var EG_THW_STOMP_FLING = [0, 190, 220, 250];  // px outward fling
// Ceiling collapse (60% gate)
var EG_THW_COLLAPSE_MARKS = [0, 6, 8, 10];  // rubble marks per boss phase
var EG_THW_COLLAPSE_MARK_MS = 1150;         // per-mark telegraph
var EG_THW_COLLAPSE_STAGGER_MS = 380;       // between marks
var EG_THW_COLLAPSE_DMG = 0.11;             // %maxHP per falling stone
var EG_THW_AFTERSHOCK_MS = 2600;            // dust cloud lingers (visual)
// Mini-thwomp siege (30% gate)
var EG_THW_MINI_N = [0, 3, 4, 5];           // minis per boss phase
var EG_THW_MINI_HOP_MS = 700;               // per hop
var EG_THW_MINI_SPEED = [0, 150, 165, 180]; // px/s hop-chase speed
var EG_THW_MINI_R = 34;                     // impact radius per mini slam
var EG_THW_MINI_DMG = 0.08;                 // %maxHP per mini slam
var EG_THW_MINI_SIEGE_MS = 12000;           // siege duration
// Grand Slam (charge attack)
var EG_THW_GS_FOLLOW_MS = 1000;             // shadow marker stalks you
var EG_THW_GS_LOCK_MS = 550;                // the lock tell
var EG_THW_GS_FALL_MS = 420;                // block drop time
var EG_THW_GS_DMG = [0, 0.24, 0.28, 0.34];  // %maxHP (the signature hit)
var EG_THW_GS_SHOCK_R = 200;                // shockwave ring radius
var EG_THW_GS_SHOCK_DMG = [0, 0.08, 0.09, 0.11]; // %maxHP shockwave edge


var _egThwWatcher = null;      // per-fight guardian state
