var EG_SHP_POOL_DMG      = [0, 9, 11, 13];   // %maxHP/s ice pool DoT
var EG_SHP_FRONT_DMG     = [0, 0.11, 0.13, 0.16]; // %maxHP rift-front eruption
var EG_SHP_WALL_DMG      = 0.10;             // %maxHP frost wall contact
var EG_SHP_WALKER_DMG    = [0, 0, 0.10, 0.12]; // %maxHP walker contact
var EG_SHP_SHARD_DMG     = 0.08;             // %maxHP shard shrapnel
var EG_SHP_ARM_DMG       = 0.12;             // %maxHP finale arm sweep
