var EG_GUST_WIND_RAMP_MS = 500;    // push strength fades in - a slide, not a shove
var EG_GUST_WIND_DUR = 5200;       // how long the gale blows
var EG_GUST_STORM_WARN_LEAD_MS = 2000; // lightning pre-warning before a front rolls in

