    // the ones the wall is blocking" reads at a glance.
    const rows = (typeof cur !== 'undefined' && cur && cur.grid) ? cur.grid.length : 0;
    const cols = rows ? (cur.grid[0] ? cur.grid[0].length : 0) : 0;
