    const [lx, ly] = Ls[Math.floor(Math.random() * Ls.length)];
    const cell = Math.min(W, H) / 8;
    const x = Math.max(60, Math.min(W - 60, tx + lx * cell));
    const y = Math.max(60, Math.min(H - 120, ty + ly * cell));
