    el.style.left = Math.round(x) + 'px';
    el.style.top = Math.round(y) + 'px';
    el.style.width = el.style.height = Math.round(r * 2) + 'px';
    el.style.marginLeft = el.style.marginTop = (-r) + 'px';
    return el;
