                if (EG_MAP_TIER_MONSTER_LEVELS[i] < base && base < EG_MAP_TIER_MONSTER_LEVELS[i + 1]) { gap = EG_MAP_TIER_MONSTER_LEVELS[i + 1] - base; break; }
