            const fam = (typeof _egGetEquippedWeaponInfo === 'function')
                ? _egGetEquippedWeaponInfo().family : 'sword';
            const face = (typeof _egFacingFromVector === 'function')
                ? _egFacingFromVector(dx, dy) : 'down';
