// Creates and injects the gate screen DOM element on first call.
// Also ensures the hub screen exists so its delegated DnD/currency
// listeners (_egBindDragEvents) are active for the gate as well.
function _egCreateGateScreen() {
    if (typeof ensureEndgameHubScreen === 'function') ensureEndgameHubScreen();
    _egInjectAtlasHighlightStyles();
    _egInjectGateLevelChipStyles();
    const screen = document.createElement('div');
    screen.id = 'screen-endgame-gate';
    screen.className = 'screen';
    screen.innerHTML = _egBuildGateFullScreenHTML();
    document.body.appendChild(screen);
    // Populate the freshly created level chip (uses current STATE values).
    try { _egRenderGateLevelChip(); } catch (e) {}
}

// Ensures the gate screen element exists in the DOM; creates it on first call.
function ensureEndgameGateScreen() {
    if (!document.getElementById('screen-endgame-gate')) {
        _egCreateGateScreen();
    }
}

// Name of the global function the BACK button calls - set by
// showEndgameGate(backFn). Defaults to the Nexus of Worlds.
var _egGateBackFn = EG_SCREEN_NAV.nexus;

// Transitions to the Probability Gate screen and refreshes all rendered zones.
// This is the main entry point called from elsewhere in the codebase.
// An optional backFn argument (name of a global function, e.g.
// 'showEndgameHub') overrides where the BACK button returns to - used
// when the gate is opened from the endgame hub character sheet.
function showEndgameGate(backFn) {
    if (typeof backFn === 'string') _egGateBackFn = _egResolveBackFn(backFn, EG_SCREEN_NAV.nexus);
    else _egGateBackFn = EG_SCREEN_NAV.nexus;
    ensureEndgameGateScreen();

    // Migrate old gate screens that were built before the side-by-side
    // layout (Orbs & Shards left of the gate) or before the atlas legend / tier tabs.
    const gateScreen = document.getElementById('screen-endgame-gate');
    if (gateScreen && (!gateScreen.querySelector('.eg-atlas-legend-hint') || !gateScreen.querySelector('.eg-gate-main') || !gateScreen.querySelector('.eg-map-stash-tabs') || !gateScreen.querySelector('.eg-gate-info-btn') || !gateScreen.querySelector('#eg-gate-level-chip') || !gateScreen.querySelector('#eg-gate-tier-strip') || !gateScreen.querySelector('#eg-potential-drops'))) {
        gateScreen.innerHTML = _egBuildGateFullScreenHTML();
    }
    _egInjectAtlasHighlightStyles();
    _egInjectMapStashTabStyles();
    _egInjectGateLevelChipStyles();
    _egInjectGateTierStripStyles();
    // The tier strip uses the atlas module's ega-tier-* classes; make sure its
    // stylesheet exists even if the atlas screen was never opened this session.
    if (typeof _egAtlasEnsureStyles === 'function') _egAtlasEnsureStyles();

    // The gate screen DOM is built once - keep the back button in sync
    // with the current return target.
    const backBtn = document.querySelector('#screen-endgame-gate .eg-back-btn');
    if (backBtn) backBtn.setAttribute('onclick', `${_egGateBackFn}()`);

    if (typeof switchScreen === 'function') {
        switchScreen('screen-endgame-gate');
    } else {
        document.querySelectorAll('.screen').forEach(s => s.style.display = 'none');
        document.getElementById('screen-endgame-gate').style.display = 'block';
    }

    _egLoadHubState();
    // Re-sync tier tabs + grid to persisted active tier (may have changed via migration)
    try {
        const activeTier = _egMapStashActiveTier || 1;
        const tabsEl = document.getElementById('eg-map-stash-tabs');
        const gridEl = document.getElementById('eg-map-stash-grid');
        if (gridEl) {
            // rebuild tabs if missing or stale
            const needTabsRebuild = !tabsEl || tabsEl.querySelectorAll('.eg-map-tab').length !== 16;
            if (needTabsRebuild) {
                const section = document.querySelector('.eg-map-stash-section');
                if (section) {
                    const oldTabs = section.querySelector('.eg-map-stash-tabs');
                    if (oldTabs) oldTabs.remove();
                    const labelEl = section.querySelector('.eg-panel-label');
                    if (labelEl) labelEl.insertAdjacentHTML('afterend', _egBuildMapStashTabsHTML());
                    else section.insertAdjacentHTML('afterbegin', _egBuildMapStashTabsHTML());
                }
            } else {
                // just sync active highlight
                document.querySelectorAll('#eg-map-stash-tabs .eg-map-tab').forEach(el => {
                    el.classList.toggle('eg-map-tab-active', +el.dataset.tier === activeTier);
                });
            }
            // rebuild grid to reflect tier's current row count (handles expansion / migration)
            gridEl.innerHTML = _egBuildMapStashGridHTMLForTier(activeTier);
            gridEl.style.gridTemplateColumns = `repeat(${EG_MAP_STASH_COLS}, 1fr)`;
        }
    } catch(e) {}
    _egRenderMapSlot();
    _egRenderMapStash();
    _egRenderCurrencyStash();
    _egRenderGateLevelChip();
    _egRenderGateTierStrip();
    _egClearTooltip();
}
