            id: `map_${Date.now()}_${Math.floor(Math.random() * 10000)}`,
            baseId: 'atlas_map',
            name,
            baseName: normalName,
            icon: '🗺️',

            category: 'map',
            type: 'map',
            rarity: 'common',

            mapTier,
            atlasNodeId,
            itemLevel: monsterLevel,
            monsterLevel,
            mods: [],
