// Injected via JS, same pattern as ensureLSTooltipStyles() in
// screens-level-select.js - avoids needing to touch the (large) main CSS file.

function _egtEnsureStyles() {
    if (document.getElementById('egt-test-hub-style')) return;

    const style = document.createElement('style');
    style.id = 'egt-test-hub-style';
    style.textContent = `
        .egt-hub-layout {
            width: 100%; height: 100%; display: flex; flex-direction: column;
            padding: 16px; box-sizing: border-box; font-family: var(--PX, monospace);
            color: var(--accent2, #e8daef); overflow-y: auto;
        }
        .egt-topbar {
            display: flex; align-items: center; justify-content: space-between;
            margin-bottom: 18px; gap: 10px; flex-wrap: wrap;
        }
        .egt-topbar-title { font-size: 16px; letter-spacing: 2px; color: var(--accent, #c8a84b); }
        .egt-map-grid {
            display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
            gap: 16px;
        }
        .egt-map-card {
            background: rgba(20, 15, 5, 0.6); border: 1px solid var(--accent, #c8a84b);
            border-radius: 6px; padding: 14px; cursor: pointer;
            display: flex; flex-direction: column; gap: 6px;
            transition: transform 0.15s, box-shadow 0.15s;
        }
        .egt-map-card:hover {
            transform: translateY(-3px);
            box-shadow: 0 4px 14px rgba(200, 168, 75, 0.35);
        }
        .egt-map-tier { font-size: 10px; opacity: 0.6; letter-spacing: 1px; }
        .egt-map-icon { font-size: 28px; }
        .egt-map-name { font-size: 13px; color: var(--accent, #c8a84b); }
        .egt-map-stats { display: flex; flex-direction: column; gap: 2px; margin: 4px 0; }
        .egt-map-stat { font-size: 10px; opacity: 0.85; }
        .egt-map-desc { font-size: 9px; opacity: 0.6; line-height: 1.4; flex-grow: 1; }
        .egt-enter-btn { margin-top: 8px; font-size: 10px; padding: 6px; }
        .egt-topbar .title-btn {
            font-family: var(--PX, monospace);
            font-size: 10px;
            letter-spacing: 1px;
            background: linear-gradient(180deg, rgba(255,255,255,0.06), rgba(0,0,0,0.25)), var(--surface, #1a1a2e);
            border: 1px solid var(--border2, #444);
            color: var(--accent2, #ccc);
            padding: 8px 16px;
            cursor: pointer;
            white-space: nowrap;
            transition: all 0.12s;
        }
        .egt-topbar .title-btn:hover {
            border-color: var(--accent, #c8a84b);
            color: var(--accent, #c8a84b);
            background: linear-gradient(180deg, rgba(200,168,75,0.12), rgba(0,0,0,0.25)), var(--surface, #1a1a2e);
            box-shadow: 0 0 10px rgba(200, 168, 75, 0.25);
        }
        .egt-topbar .title-btn:active {
            transform: translateY(1px);
            box-shadow: none;
        }
     `;
    document.head.appendChild(style);
}


//------------------------------------------------------------------------
//-------------------SCREEN BOOTSTRAP----------------------------------------
//------------------------------------------------------------------------

function _egtCreateScreen() {
    _egtEnsureStyles();
    const screen = document.createElement('div');
    screen.id = 'screen-endgame-test-hub';
    screen.className = 'screen';
    screen.innerHTML = _egtBuildFullScreenHTML();
    document.body.appendChild(screen);
}

function ensureEndgameTestHubScreen() {
    if (!document.getElementById('screen-endgame-test-hub')) _egtCreateScreen();
}

// Entry point - call this to show the map-select screen.
// (History push happens in launchEndgameTestMode() in screens.js on first
// entry; goToLevelSelect() calls this directly to return here after a run.)
function showEndgameTestHub() {
    ensureEndgameTestHubScreen();
    switchScreen('screen-endgame-test-hub');
}
//--- globalThis bridge (function/var): js/endgame-testing-screen.js ---
try { globalThis["_egtPickSeedGi"] = _egtPickSeedGi; } catch (e) {}
try { globalThis["_egLaunchTestMap"] = _egLaunchTestMap; } catch (e) {}
try { globalThis["_egtBuildMapCardHTML"] = _egtBuildMapCardHTML; } catch (e) {}
try { globalThis["_egtBuildFullScreenHTML"] = _egtBuildFullScreenHTML; } catch (e) {}
try { globalThis["_egtEnsureStyles"] = _egtEnsureStyles; } catch (e) {}
try { globalThis["_egtCreateScreen"] = _egtCreateScreen; } catch (e) {}
try { globalThis["ensureEndgameTestHubScreen"] = ensureEndgameTestHubScreen; } catch (e) {}
try { globalThis["showEndgameTestHub"] = showEndgameTestHub; } catch (e) {}
try { globalThis["EG_TEST_MAPS"] = EG_TEST_MAPS; } catch (e) {}

//=======[ js/endgame/endgame-puzzle-generator.js ]=======================================================
//------------------------------------------------------------------------
//-------------------ENDGAME PUZZLE GENERATOR-----------------------------
//------------------------------------------------------------------------
// Procedurally generates nonogram puzzle levels for endgame map runs so
// the chain is no longer limited to story puzzles from the world list.
//
// Two generation modes:
//   'symbol' - rasterises a glyph onto an offscreen canvas (Greek letters,
//              math operators, card suits, weather, ... any Unicode symbol)
//              and downsamples the pixels into a binary solution grid
//   'random' - random structures of various sizes: drunkard-walk blobs,
//              refined by cellular-automata smoothing, optionally mirrored
//   'mixed'  - per puzzle: 70% symbol / 30% random
//
// Generated levels are appended to ALL and flagged with isGeneratedPuzzle
// so _egBuildChainPool() never leaks them into the story pool. They carry
// a real world number (random 1..WORLDS.length) so backgrounds, BGM and
// all cur.world consumers keep working unchanged.
//
// Entry point:
//   _egCreateGeneratedLevel(opts) → gi | null
//     opts: { mode:'symbol'|'random'|'mixed', tier:Number, minCells:Number }
//------------------------------------------------------------------------


//------------------------------------------------------------------------
//-------------------SYMBOL POOLS-----------------------------------------
//------------------------------------------------------------------------

